import { Router } from "express";
import { OrganizationBillingController } from "./organizationbilling.controller";
import { auth } from "../../middleware/checkAuth";
import { validationRequest } from "../../middleware/validationRequest";
import { submitPaymentSchema, upgradePlanSchema } from "./organizationbilling.validation";
import { OrganizationRole } from "../../../../generated/prisma/enums";
const router = Router({ mergeParams: true });
router.get("/", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN, OrganizationRole.PROJECT_MANAGER] }), OrganizationBillingController.getBillingOverview);
router.get("/plan", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN, OrganizationRole.PROJECT_MANAGER] }), OrganizationBillingController.getBillingOverview);
router.get("/usage", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN, OrganizationRole.PROJECT_MANAGER] }), OrganizationBillingController.getUsage);
router.get("/invoices", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), OrganizationBillingController.getInvoices);
router.get("/payments", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), OrganizationBillingController.getPayments);
router.post("/payments", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), validationRequest(submitPaymentSchema), OrganizationBillingController.submitPayment);
router.post("/upgrade", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), validationRequest(upgradePlanSchema), OrganizationBillingController.requestUpgrade);
router.post("/downgrade", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), validationRequest(upgradePlanSchema), OrganizationBillingController.requestDowngrade);
router.post("/cancel", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), OrganizationBillingController.cancelSubscription);
router.post("/resume", auth({ organizationRoles: [OrganizationRole.ORG_ADMIN] }), OrganizationBillingController.resumeSubscription);
export const OrganizationBillingRoutes = router;
